	@Test
	void topLevelIdentityProjectionExportsIndependentRowsWithExactColumns() {
		var secondKey = VF.createLiteral("another key");
		var first = new CountingStatement(EVENT, KEY);
		var second = new CountingStatement(EVENT, secondKey);
		var root = new QueryRoot(projection(pattern("event", "key"), new ProjectionElem("key")));
		var rows = evaluate(root, List.of(first, second), EmptyBindingSet.getInstance(), null);
		assertThat(rows).extracting(binding -> binding.getValue("key")).containsExactly(KEY, secondKey);
		assertThat(rows).allSatisfy(binding -> assertThat(binding.getBindingNames()).containsExactly("key"));
		assertThat(rows.getFirst()).isNotSameAs(rows.getLast());
		((MutableBindingSet) rows.getFirst()).setBinding("key", GRAPH);
		assertThat(rows.getLast().getValue("key")).isEqualTo(secondKey);
		assertThat(first.subjectReads + second.subjectReads).isZero();
	}

